// Generate a random buffer (1..4096 bytes)
std::string buf = FUZZ_PARAM_STR();

// Choose a non-negative length within the buffer bounds to satisfy the
// requirement that data must reference at least `len` readable bytes.
// len in [0, buf.size()].
int len = (int)(*FUZZ_PARAM(unsigned int) % (buf.size() + 1));

// Select the data pointer according to len:
// - If len > 0: must point to at least len readable bytes -> use buf.data().
// - If len == 0: optionally pass nullptr to exercise that path without dereference.
const unsigned char *data_ptr = nullptr;
unsigned int flag = *FUZZ_PARAM(unsigned int);
if (len > 0) {
    data_ptr = reinterpret_cast<const unsigned char*>(buf.data());
} else {
    data_ptr = (flag & 1) ? nullptr : reinterpret_cast<const unsigned char*>(buf.data());
}

// Invoke the target function. Capture the result to avoid optimizing the call away.
volatile int sum = mc_sum_bytes(data_ptr, len);
(void)sum;

// Validation summary:
// - Enforced len >= 0 and, when len > 0, data_ptr points to a buffer with at least len bytes.
// - When len == 0, we may pass nullptr to explore that code path without violating constraints.
